import time
import random
from bisect import bisect_left, insort
from collections import deque, defaultdict


def pack(payload):
    items = list(payload["items"])
    capacity = payload["capacity"]
    n = len(items)
    if n == 0:
        return []
    if capacity is None or capacity <= 0:
        return [[i] for i in range(n)]

    start = time.time()
    BUDGET = 0.75  # seconds per instance
    rng = random.Random(0xBADC0DE)

    total = sum(items)
    lb = max(1, -(-total // capacity))

    order_desc = sorted(range(n), key=lambda i: (-items[i], i))
    bl, ins = bisect_left, insort

    # ---------- Best-Fit Decreasing (bisect-accelerated) ----------
    def best_fit(seq):
        rem_list = []
        rem_map = {}
        bins, loads = [], []
        for i in seq:
            s = items[i]
            if s > capacity:
                bins.append([i]); loads.append(s)
                continue
            pos = bl(rem_list, s)
            if pos < len(rem_list):
                r = rem_list.pop(pos)
                dq = rem_map[r]; b = dq.popleft()
                if not dq: del rem_map[r]
                bins[b].append(i); loads[b] += s
                r -= s
            else:
                b = len(bins); bins.append([i]); loads.append(s)
                r = capacity - s
            if r > 0:
                ins(rem_list, r)
                dq = rem_map.get(r)
                if dq is None: rem_map[r] = deque([b])
                else: dq.append(b)
        return bins, loads

    best_bins, best_loads = best_fit(order_desc)
    best_k = len(best_bins)

    def time_left():
        return (time.time() - start) < BUDGET

    # ---------- bin-dispersal local search ----------
    def disperse_pass(bins, loads):
        m = len(bins)
        open_bins = sorted((b for b in range(m) if bins[b]), key=lambda b: loads[b])
        if len(open_bins) <= 1:
            return False
        max_targets = m if m <= 200 else 120
        improved = False
        for t in open_bins[:max_targets]:
            if not bins[t] or not time_left():
                continue
            pairs = sorted((capacity - loads[b], b) for b in range(m)
                           if b != t and bins[b] and loads[b] < capacity)
            rem_list = [p[0] for p in pairs]
            rem_map = {}
            for r, b in pairs:
                dq = rem_map.get(r)
                if dq is None: rem_map[r] = deque([b])
                else: dq.append(b)
            ok, plan = True, []
            for i in sorted(bins[t], key=lambda i: -items[i]):
                s = items[i]
                pos = bl(rem_list, s)
                if pos == len(rem_list):
                    ok = False; break
                r = rem_list.pop(pos)
                dq = rem_map[r]; b = dq.popleft()
                if not dq: del rem_map[r]
                plan.append((i, b))
                r -= s
                if r > 0:
                    ins(rem_list, r)
                    dq = rem_map.get(r)
                    if dq is None: rem_map[r] = deque([b])
                    else: dq.append(b)
            if ok:
                for i, b in plan:
                    bins[b].append(i); loads[b] += items[i]
                bins[t] = []; loads[t] = 0
                improved = True
        return improved

    def run_dispersal(bins, loads):
        k = sum(1 for b in bins if b)
        while k > lb and time_left():
            if not disperse_pass(bins, loads):
                break
            k = sum(1 for b in bins if b)
        return k

    best_k = run_dispersal(best_bins, best_loads)

    def consider(bins):
        nonlocal best_bins, best_loads, best_k
        k = sum(1 for b in bins if b)
        if k < best_k:
            best_bins = bins
            best_loads = [sum(items[i] for i in b) for b in bins]
            best_k = run_dispersal(best_bins, best_loads)
            return True
        return False

    # ---------- exact-pattern greedy: repeated max-fill knapsack ----------
    # applicable when items are positive ints with few distinct sizes
    pat_ok = True
    for s in items:
        if not isinstance(s, int) or s < 0:
            pat_ok = False
            break
    by_size = None
    ok_sizes = None
    if pat_ok and 0 < capacity <= 200000:
        by_size = defaultdict(deque)
        for i in range(n):
            by_size[items[i]].append(i)
        ok_sizes = sorted(v for v in by_size if 0 < v <= capacity)
        if not ok_sizes or len(ok_sizes) > 64 or capacity // ok_sizes[0] > 3000:
            ok_sizes = None

    def pattern_greedy(order):
        d = len(order)
        queues = {v: by_size[v].copy() for v in order}
        cnt = {v: len(by_size[v]) for v in order}
        mask_cap = (1 << (capacity + 1)) - 1
        bins = []
        left = sum(cnt.values())
        while left > 0:
            masks = [1] * (d + 1)
            for j in range(d - 1, -1, -1):
                s = order[j]
                c = cnt[s]
                m = masks[j + 1]
                p = 1
                while c > 0:
                    take = p if p <= c else c
                    m |= m << (s * take)
                    c -= take
                    p <<= 1
                masks[j] = m
            low = masks[0] & mask_cap
            t = low.bit_length() - 1
            if t <= 0:
                return None
            if rng.random() < 0.08:
                low &= ~(1 << t)
                t2 = low.bit_length() - 1
                if t2 > 0:
                    t = t2
            rem = t
            picks = []
            for j in range(d):
                s = order[j]
                c = cnt[s]
                nxt = masks[j + 1]
                kmax = rem // s
                if kmax > c:
                    kmax = c
                chosen = 0
                if rng.random() < 0.5:
                    for k in range(kmax, -1, -1):
                        r = rem - s * k
                        if (nxt >> r) & 1:
                            chosen = k; rem = r
                            break
                else:
                    for k in range(kmax + 1):
                        r = rem - s * k
                        if (nxt >> r) & 1:
                            chosen = k; rem = r
                            break
                if chosen:
                    picks.append((s, chosen))
            if rem != 0:
                return None
            b_items = []
            for s, k in picks:
                q = queues[s]
                for _ in range(k):
                    b_items.append(q.popleft())
                cnt[s] -= k
                left -= k
            bins.append(b_items)
        return bins

    def pattern_phase(deadline, stale_limit):
        if ok_sizes is None:
            return
        zero_items = list(by_size.get(0, ()))
        big_items = []
        for v in by_size:
            if v > capacity:
                big_items.extend(by_size[v])
        tries = stale = 0
        while best_k > lb and tries < 400 and stale < stale_limit:
            now = time.time()
            if now >= deadline or not time_left():
                break
            tries += 1
            order = ok_sizes[:]
            if tries > 1 and rng.random() < 0.5:
                rng.shuffle(order)
            bins = pattern_greedy(order)
            if bins is None:
                stale += 1
                continue
            if zero_items:
                if bins:
                    bins[0].extend(zero_items)
                else:
                    bins = [list(zero_items)]
            for i in big_items:
                bins.append([i])
            if consider(bins):
                stale = 0
            else:
                stale += 1

    # ---------- randomized restarts (perturbed descending orders) ----------
    groups = []
    i = 0
    while i < n:
        j = i
        v = items[order_desc[i]]
        while j < n and items[order_desc[j]] == v:
            j += 1
        groups.append((i, j)); i = j

    def perturb_burst(max_iter, deadline):
        c = 0
        while best_k > lb and c < max_iter:
            if time.time() >= deadline or not time_left():
                break
            c += 1
            if rng.random() < 0.5:
                seq = order_desc[:]
                for a, b in groups:
                    if b - a > 1:
                        seg = seq[a:b]; rng.shuffle(seg); seq[a:b] = seg
            else:
                eps = rng.choice((0.005, 0.02, 0.06))
                seq = sorted(range(n), key=lambda i: -items[i] * (1.0 + eps * (rng.random() - 0.5)))
            bins2, _ = best_fit(seq)
            consider(bins2)

    # ---------- interleaved search ----------
    while best_k > lb and time_left():
        pattern_phase(min(time.time() + 0.12, start + BUDGET), 15)
        if best_k > lb and time_left():
            perturb_burst(60, min(time.time() + 0.12, start + BUDGET))

    return [b for b in best_bins if b]
